简单记录花了几天时间，不算太理解，但代码能写就行了吧。手算一遍，代码逻辑保持一致即可。
时间复杂度 O(m+n)init_next_arr 时间复杂度 O(n)
代码实现1.暴力法
#include &lt;stdio.h&gt;int main()&#123;    char str1[] = &quot;abcbcglx&quot;;    char pat[] = &quot;bcgl&quot;;    int pat_size = sizeof(pat) / sizeof(pat[0]) - 1;    int str1_size = sizeof(str1) / sizeof(str1[0]) - pat_size;    int i = 0;    int j = 0;    int k = 0; //失败后从str1的下一个字母开始比较    while (j &lt; pat_size &amp;&amp; i &lt; str1_size)    &#123;        k = i;        while (pat[j] == str1[k]) &#123;            k++;            j++;        &#125;        if (j &lt; pat_size) &#123;            i++;            j = 0;        &#125;    &#125;    if (j == pat_size)    &#123;        printf(&quot;%d&quot;, i);    &#125;    return 0;&#125;
2.kmp
#include &lt;stdio.h&gt;void print_arr(int *arr, int size) &#123;    for (int i = 0; i &lt; size; i++) &#123;        printf(&quot;%d &quot;, arr[i]);    &#125;    printf(&quot;\n&quot;);&#125;void init_next_arr(int *next, char *pat, int pat_size) &#123;    int i = 1;    int j = 0;        next[0] = 0;    while (i &lt; pat_size) &#123;        if (pat[i] == pat[j]) &#123;            next[i] = j + 1;            i++;            j++;        &#125; else &#123;            if (j &gt; 0) &#123;                j = next[j-1];             &#125; else &#123;                next[i] = 0;                i++;            &#125;        &#125;    &#125;&#125;int main()&#123;    char str1[] = &quot;abcxabcdabxabdabcdabcy&quot;;    //char pat[] = &quot;bcgl&quot;;    char pat[] = &quot;abdab&quot;;    int pat_size = sizeof(pat) / sizeof(pat[0]) - 1;    int str1_size = sizeof(str1) / sizeof(str1[0]) - 1;    int next[pat_size];    init_next_arr(next, pat, pat_size);    int i = 0;    int j = 0;    while (j &lt; pat_size &amp;&amp; i &lt; str1_size) &#123;        if (str1[i] == pat[j]) &#123;            i++;            j++;        &#125; else &#123;            if (j &gt; 0) &#123;                j = next[j-1];            &#125; else &#123;                i++;            &#125;        &#125;    &#125;    print_arr(next, pat_size);    printf(&quot;%d\n&quot;, i-j);    return 0;&#125;
